236	    @Override
237	    @Transactional
238	    public void saveOwner(Owner owner) throws DataAccessException {
239	        if (owner.isNew() && ownerRepository.existsByTelephone(owner.getTelephone())) {
240	            throw new DuplicateTelephoneException(owner.getTelephone());
241	        }
242	        if (owner.isNew()
243	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
244	            throw new CityOwnerLimitExceededException(owner.getCity());
245	        }
246	        if (owner.isNew()) {
247	            List<Owner> householdMembers = findHouseholdMembers(owner);
248	            if (!householdMembers.isEmpty()) {
249	                if (!owner.isSharesHousehold()) {
250	                    throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
251	                }
252	                owner.setHouseholdId(resolveHouseholdId(householdMembers));
253	            }
254	        }
255	        if (owner.getRegistrationDate() == null) {
256	            owner.setRegistrationDate(LocalDate.now());
257	        }
258	        if (owner.isNew() && owner.getCustomerCode() == null) {
259	            owner.setCustomerCode(generateCustomerCode(owner));
260	        }
261	        if (owner.isNew()) {
262	            owner.setNamesakeCount(countNamesakes(owner));
263	        }
264	        if (owner.getMembershipNumber() == null) {
265	            owner.setMembershipNumber(generateMembershipNumber(owner));
266	        }
267	        ownerRepository.save(owner);
268	
269	    }
270	
271	    /**
272	     * Count the owners that already exist (before this create) sharing the same first name and last
273	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
274	     * unique among the existing owners.
275	     */
276	    private int countNamesakes(Owner owner) {
277	        String firstName = owner.getFirstName();
278	        String lastName = owner.getLastName();
279	        if (firstName == null || lastName == null) {
280	            return 0;
281	        }
282	        return (int) ownerRepository.findAll().stream()
283	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
284	                && lastName.equalsIgnoreCase(existing.getLastName()))
285	            .count();
286	    }
287	
288	    /**
289	     * Find the owners that already belong to the same household as {@code owner}, i.e. have the same
290	     * last name and the same address. Last names are compared case-insensitively with collapsed
291	     * whitespace; addresses are compared in their canonical normalized form (see
292	     * {@link AddressNormalizer}), so differences in letter case, runs of spaces or street-type
293	     * abbreviations are ignored. Returns an empty list when the owner has no last name or address to
294	     * match on.
295	     */
296	    private List<Owner> findHouseholdMembers(Owner owner) {
297	        String lastName = normalizeHouseholdKey(owner.getLastName());
298	        String address = AddressNormalizer.normalize(owner.getAddress());
299	        if (lastName == null || address == null) {
300	            return List.of();
301	        }
302	        return ownerRepository.findAll().stream()
303	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
304	                && address.equals(AddressNormalizer.normalize(existing.getAddress())))
305	            .toList();
306	    }
307	
308	    /**
309	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
310	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
311	     * new one is generated. The resolved value is back-filled onto every member that is missing it
312	     * (or has a different one) so all members of the household share the same identifier.
313	     */
314	    private String resolveHouseholdId(List<Owner> members) {
315	        String householdId = members.stream()
316	            .map(Owner::getHouseholdId)
317	            .filter(id -> id != null && !id.isBlank())
318	            .findFirst()
319	            .orElseGet(() -> UUID.randomUUID().toString());
320	        for (Owner member : members) {
321	            if (!householdId.equals(member.getHouseholdId())) {
322	                member.setHouseholdId(householdId);
323	                ownerRepository.save(member);
324	            }
325	        }
326	        return householdId;
327	    }
328	
329	    /**
330	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
331	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
332	     */
333	    private String normalizeHouseholdKey(String value) {
334	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
335	    }
336	
337	    /**
338	     * Build an owner's {@code customerCode} as {@code '<CITY3>-<LAST3>-<NNNN>'}: CITY3 is the
339	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
340	     * letters of the owner's last name, and NNNN a per-city 4-digit zero-padded sequence equal
341	     * to one more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
342	     */
343	    private String generateCustomerCode(Owner owner) {
344	        String city3 = upperPrefix3(owner.getCity());
345	        String last3 = upperPrefix3(owner.getLastName());
346	        long sequence = countOwnersInCity(owner) + 1L;
347	        return String.format("%s-%s-%04d", city3, last3, sequence);
348	    }
349	
350	    /**
351	     * Return the upper-cased first three letters of {@code value} (or fewer when it is shorter),
352	     * the shared truncate-and-upper idiom used for each {@code customerCode} prefix segment.
353	     */
354	    private String upperPrefix3(String value) {
355	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
356	    }
357	
358	    /**
359	     * Count the owners that already exist (before this create) in the same city as {@code owner},
360	     * compared case-insensitively.
361	     */
362	    private long countOwnersInCity(Owner owner) {
363	        String city = owner.getCity();
364	        return ownerRepository.findAll().stream()
365	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
366	            .count();
367	    }
368	
369	    /**
370	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
371	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
372	     */
373	    private String generateMembershipNumber(Owner owner) {
374	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
375	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
376	    }
377	
378	    @Override
379	    @Transactional(readOnly = true)
380	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
381	        return ownerRepository.findByLastName(lastName);
382	    }
383	
384	    @Override
385	    @Transactional(readOnly = true)
386	    public Collection<Visit> findVisitsByPetId(int petId) {
387	        return visitRepository.findByPetId(petId);
388	    }
389	
390	    @Override
391	    @Transactional(readOnly = true)
392	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
393	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
394	    }
395	
396	    private <T> T findEntityById(Supplier<T> supplier) {
397	        try {
398	            return supplier.get();
399	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
400	            // Just ignore not found exceptions for Jdbc/Jpa realization
401	            return null;
402	        }
403	    }
404	
405	}
