44	/**
45	 * Global Exception handler for REST controllers.
46	 * <p>
47	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
48	 *
49	 * @author Vitaliy Fedoriv
50	 * @author Alexander Dudkin
51	 */
52	@ControllerAdvice
53	public class ExceptionControllerAdvice {
54	
55	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
56	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
57	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
58	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
59	
60	    /**
61	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
62	     * class.
63	     *
64	     * @param e     Object referring to the thrown exception.
65	     * @param status HTTP response status.
66	     * @param url URL request.
67	     */
68	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
69	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
70	        problemDetail.setType(URI.create(url.toString()));
71	        problemDetail.setTitle(e.getClass().getSimpleName());
72	        problemDetail.setDetail(detail);
73	        problemDetail.setProperty("timestamp", Instant.now());
74	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
75	        return problemDetail;
76	    }
77	
78	    /**
79	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
80	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
81	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
82	     * would catch it and report an authorization failure as a 500.
83	     *
84	     * @param e The {@link AccessDeniedException} to propagate
85	     * @throws AccessDeniedException always
86	     */
87	    @ExceptionHandler(AccessDeniedException.class)
88	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
89	        throw e;
90	    }
91	
92	    /**
93	     * Handles {@link DuplicateTelephoneException}, raised by the service layer when a new owner's normalized
94	     * telephone is already used by another owner, by returning a 409 Conflict status.
95	     *
96	     * @param e The {@link DuplicateTelephoneException} to be handled
97	     * @param request {@link HttpServletRequest} object referring to the current request.
98	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
99	     */
100	    @ExceptionHandler(DuplicateTelephoneException.class)
101	    @ResponseBody
102	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
103	        logger.warn("Duplicate telephone at {} {}: {}",
104	            request.getMethod(),
105	            request.getRequestURI(),
106	            e.getMessage());
107	        HttpStatus status = HttpStatus.CONFLICT;
108	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
109	        return ResponseEntity.status(status).body(detail);
110	    }
111	
112	    /**
113	     * Handles {@link DuplicateHouseholdException}, raised by the service layer when a new owner shares
114	     * the same last name and address as an existing owner and the request did not opt in via
115	     * {@code sharesHousehold}, by returning a 409 Conflict status.
116	     *
117	     * @param e The {@link DuplicateHouseholdException} to be handled
118	     * @param request {@link HttpServletRequest} object referring to the current request.
119	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
120	     */
121	    @ExceptionHandler(DuplicateHouseholdException.class)
122	    @ResponseBody
123	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
124	        logger.warn("Duplicate household at {} {}: {}",
125	            request.getMethod(),
126	            request.getRequestURI(),
127	            e.getMessage());
128	        HttpStatus status = HttpStatus.CONFLICT;
129	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
130	        return ResponseEntity.status(status).body(detail);
131	    }
132	
133	    /**
134	     * Handles {@link CityOwnerLimitExceededException}, raised by the service layer when a new owner's
135	     * city already contains the maximum number of owners, by returning a 409 Conflict status.
136	     *
137	     * @param e The {@link CityOwnerLimitExceededException} to be handled
138	     * @param request {@link HttpServletRequest} object referring to the current request.
139	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
140	     */
141	    @ExceptionHandler(CityOwnerLimitExceededException.class)
142	    @ResponseBody
143	    public ResponseEntity<ProblemDetail> handleCityOwnerLimitExceededException(CityOwnerLimitExceededException e, HttpServletRequest request) {
144	        logger.warn("City owner limit exceeded at {} {}: {}",
145	            request.getMethod(),
146	            request.getRequestURI(),
147	            e.getMessage());
148	        HttpStatus status = HttpStatus.CONFLICT;
149	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
150	        return ResponseEntity.status(status).body(detail);
151	    }
152	
153	    /**
154	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
155	     *
156	     * @param e The {@link Exception} to be handled
157	     * @param request {@link HttpServletRequest} object referring to the current request.
158	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
159	     */
160	    @ExceptionHandler(Exception.class)
161	    @ResponseBody
162	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
163	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
164	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
